import random

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)

    answer = n * (n - 1) * (n - 2) // 6

    check = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = f"Let A be a set of {n} distinct positive integers. Find the maximum possible number of distinct sums that can be formed by adding any three distinct elements of A. State only the integer."
    return problem, str(answer)


